import{_ as a,o as t,c as l,a2 as i}from"./chunks/framework.CDU0sSpB.js";const p=JSON.parse('{"title":"3.2 观察桌面与人工接管","description":"让用户看见操作过程，并能暂停、接管和交还。","frontmatter":{"title":"3.2 观察桌面与人工接管","description":"让用户看见操作过程，并能暂停、接管和交还。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-3/3-2.md","filePath":"delivery/stage-3/3-2.md","lastUpdated":null}'),r={name:"delivery/stage-3/3-2.md"};function o(n,e,s,d,_,c){return t(),l("div",null,[...e[0]||(e[0]=[i('<h1 id="_3-2-观察桌面与人工接管" tabindex="-1">3.2 观察桌面与人工接管 <a class="header-anchor" href="#_3-2-观察桌面与人工接管" aria-label="Permalink to &quot;3.2 观察桌面与人工接管&quot;">​</a></h1><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让用户能看见 Hearth 正在操作的窗口和步骤，并在需要时暂停自动操作、自己接管、完成后再交还。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>显示当前窗口、操作步骤和下一步计划，避免用户不知道系统在做什么。</li><li>提供暂停、继续、接管和终止四个明确动作。</li><li>用户接管时立即停止自动输入，交还时先确认当前状态再继续。</li><li>对密码、聊天内容等敏感区域做遮挡，不把完整屏幕长期保存。</li><li>记录每次接管、暂停和终止的原因，方便事后核对。</li><li>如果无法观察窗口或无法接管，系统必须停下，不允许继续自动操作。</li></ol>',5)])])}const u=a(r,[["render",o]]);export{p as __pageData,u as default};
